// Only links explicitly generated by the app may override /feed: badge reviews and crew invitations.
const REVIEW_LINK = /^\/events\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/survey$/i;
const CREW_INVITE_LINK = /^\/crews\/join\/[A-Za-z0-9]{6,16}$/;

export function loginDestination(search: string): string {
  const next = new URLSearchParams(search).get("next");
  return next && (REVIEW_LINK.test(next) || CREW_INVITE_LINK.test(next)) ? next : "/feed";
}
